/// The new artwork `icon` draws under New icons, if it has any yet (`getNewIcon`).
pub fn new_icon(icon: &Icon) -> Option<&'static Icon> {
    match icon.name {
        "check" => Some(&CHECK),
        "check-small" => Some(&CHECK_SMALL),
        "circle-check" => Some(&CIRCLE_CHECK),
        "magnifying-glass" => Some(&MAGNIFYING_GLASS),
        "outline-dots" => Some(&OUTLINE_DOTS),
        "outline-worktree" => Some(&OUTLINE_WORKTREE),
        "branch-out" => Some(&BRANCH_OUT),
        "monitor" => Some(&MONITOR),
        "notifications" => Some(&NOTIFICATIONS),
        "copy" => Some(&COPY),
        "outline-copy" => Some(&OUTLINE_COPY),
        "code" => Some(&CODE),
        "code-slash" => Some(&CODE_SLASH),
        "cube" => Some(&CUBE),
        "lock" => Some(&LOCK),
        "sliders" => Some(&SLIDERS),
        "outline-sliders" => Some(&OUTLINE_SLIDERS),
        "trash" => Some(&TRASH),
        "outline-trash" => Some(&OUTLINE_TRASH),
        "close" => Some(&CLOSE),
        "close-small" => Some(&CLOSE_SMALL),
        "xmark-small" => Some(&XMARK_SMALL),
        "outline-xmark" => Some(&OUTLINE_XMARK),
        "server" => Some(&SERVER),
        "globe" => Some(&GLOBE),
        "outline-globe" => Some(&OUTLINE_GLOBE),
        "archive" => Some(&ARCHIVE),
        "appearance" => Some(&APPEARANCE),
        "enter" => Some(&ENTER),
        "reset" => Some(&RESET),
        "outline-reset" => Some(&OUTLINE_RESET),
        "outline-undo" => Some(&OUTLINE_UNDO),
        "window-cursor" => Some(&WINDOW_CURSOR),
        "outline-browser-annotate" => Some(&OUTLINE_BROWSER_ANNOTATE),
        "select-element" => Some(&SELECT_ELEMENT),
        "download" => Some(&DOWNLOAD),
        "post-skill" => Some(&POST_SKILL),
        "graduation-cap" => Some(&GRADUATION_CAP),
        "eye" => Some(&EYE),
        "outline-eye" => Some(&OUTLINE_EYE),
        "outline-eye-slash" => Some(&OUTLINE_EYE_SLASH),
        "chevron-down" => Some(&CHEVRON_DOWN),
        "outline-chevron-down" => Some(&OUTLINE_CHEVRON_DOWN),
        "chevron-left" => Some(&CHEVRON_LEFT),
        "chevron-right" => Some(&CHEVRON_RIGHT),
        "outline-chevron-right" => Some(&OUTLINE_CHEVRON_RIGHT),
        "arrow-up" => Some(&ARROW_UP),
        "arrow-left" => Some(&ARROW_LEFT),
        "outline-arrow-left" => Some(&OUTLINE_ARROW_LEFT),
        "arrow-right" => Some(&ARROW_RIGHT),
        "outline-arrow-right" => Some(&OUTLINE_ARROW_RIGHT),
        "plus" => Some(&PLUS),
        "plus-small" => Some(&PLUS_SMALL),
        "minus" => Some(&MINUS),
        "dash" => Some(&DASH),
        "folder" => Some(&FOLDER),
        "file-tree" => Some(&FILE_TREE),
        "folder-add-left" => Some(&FOLDER_ADD_LEFT),
        "edit" => Some(&EDIT),
        "comment" => Some(&COMMENT),
        "bubble-5" => Some(&BUBBLE_5),
        "speech-bubble" => Some(&SPEECH_BUBBLE),
        "extensions" => Some(&EXTENSIONS),
        "settings-gear" => Some(&SETTINGS_GEAR),
        "outline-square-arrow" => Some(&OUTLINE_SQUARE_ARROW),
        "square-arrow-top-right" => Some(&SQUARE_ARROW_TOP_RIGHT),
        "circle-ban-sign" => Some(&CIRCLE_BAN_SIGN),
        "window-analytics" => Some(&WINDOW_ANALYTICS),
        "providers" => Some(&PROVIDERS),
        "review" => Some(&REVIEW),
        "outline-globe-plus" => Some(&OUTLINE_GLOBE_PLUS),
        _ => None,
    }
}
